def pmf_binomial(k, n, p):
    if k < 0 or k > n:
        return 0.0
    return round(math.comb(n, k) * p ** k * (1 - p) ** (n - k), 4)

import math

def cdf_binomial(k, n, p):
    if k < 0:
        return 0.0
    if k >= n:
        return 1.0
    return round(sum(math.comb(n, i) * p ** i * (1 - p) ** (n - i) for i in range(k + 1)), 4)

