def peluang_antara(a, b, mu, sigma):
    F = lambda x: 0.5 * (1 + math.erf((x - mu) / sigma / math.sqrt(2)))
    return round(F(b) - F(a), 4)

import math

def kuantil_normal(q, mu, sigma):
    F = lambda x: 0.5 * (1 + math.erf((x - mu) / sigma / math.sqrt(2)))
    lo, hi = mu - 10 * sigma, mu + 10 * sigma
    for _ in range(100):
        mid = (lo + hi) / 2
        if F(mid) < q:
            lo = mid
        else:
            hi = mid
    return round((lo + hi) / 2, 2) + 0.0

